class Qwen25VLMLP(nn.Module):
    # Align intermediate_size to this value for cuBLAS GEMM tile efficiency.
    # E.g. 3420 -> 3456 (= 128 * 27), improving MFU from 34.8% to ~60%+.
    # Zero-padded weights don't affect forward output or gradient flow.
    """Qwen2 5 VLMLP."""
    _GEMM_ALIGN = 128

    def __init__(self, config, bias=False, use_selective_recompute=False):
        """Initialize the instance."""
        super().__init__()
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size

        # Pad intermediate_size to next multiple of _GEMM_ALIGN
        align = self._GEMM_ALIGN
        self.padded_intermediate_size = (
            (self.intermediate_size + align - 1) // align * align
        )

        self.gate_up_proj = nn.Linear(
            self.hidden_size, 2 * self.padded_intermediate_size, bias=bias
        )
        self.down_proj = nn.Linear(
            self.padded_intermediate_size, self.hidden_size, bias=bias
        )

        self.hidden_act = config.hidden_act
        self.act_fn = ACT2FN[config.hidden_act]
        self.use_selective_recompute = use_selective_recompute

    def _load_from_state_dict(
        self,
        state_dict,
        prefix,
        local_metadata,
        strict,
        missing_keys,
        unexpected_keys,
        error_msgs,
    ):
        """Pad checkpoint weights from original intermediate_size to padded size."""
        pad = self.padded_intermediate_size - self.intermediate_size
        if pad > 0:
            orig = self.intermediate_size
            # gate_up_proj.weight: [2*orig, hidden] -> [2*padded, hidden]
            key_w = prefix + "gate_up_proj.weight"
            if key_w in state_dict and state_dict[key_w].shape[0] == 2 * orig:
                w = state_dict[key_w]
                gate_w, up_w = w.split([orig, orig], dim=0)
                gate_w = F.pad(gate_w, (0, 0, 0, pad))
                up_w = F.pad(up_w, (0, 0, 0, pad))
                state_dict[key_w] = torch.cat([gate_w, up_w], dim=0)
            # gate_up_proj.bias: [2*orig] -> [2*padded]
            key_b = prefix + "gate_up_proj.bias"
            if key_b in state_dict and state_dict[key_b].shape[0] == 2 * orig:
                b = state_dict[key_b]
                gate_b, up_b = b.split([orig, orig])
                state_dict[key_b] = torch.cat(
                    [F.pad(gate_b, (0, pad)), F.pad(up_b, (0, pad))]
                )
            # down_proj.weight: [hidden, orig] -> [hidden, padded]
            key_dw = prefix + "down_proj.weight"
            if key_dw in state_dict and state_dict[key_dw].shape[1] == orig:
                state_dict[key_dw] = F.pad(state_dict[key_dw], (0, pad))
            # down_proj.bias: [hidden] - no change needed

        super()._load_from_state_dict(
            state_dict,
            prefix,
            local_metadata,
            strict,
            missing_keys,
            unexpected_keys,
            error_msgs,
        )

    def _save_to_state_dict(self, destination, prefix, keep_vars):
        """Strip padding so saved checkpoints use the original intermediate_size."""
        super()._save_to_state_dict(destination, prefix, keep_vars)
        pad = self.padded_intermediate_size - self.intermediate_size
        if pad == 0:
            return
        orig = self.intermediate_size
        padded = self.padded_intermediate_size

        # gate_up_proj.weight: [2*padded, hidden] -> [2*orig, hidden]
        key_w = prefix + "gate_up_proj.weight"
        if key_w in destination:
            w = destination[key_w]
            gate_w, up_w = w.split([padded, padded], dim=0)
            destination[key_w] = torch.cat([gate_w[:orig], up_w[:orig]], dim=0)

        # gate_up_proj.bias: [2*padded] -> [2*orig]
        key_b = prefix + "gate_up_proj.bias"
        if key_b in destination:
            b = destination[key_b]
            gate_b, up_b = b.split([padded, padded])
            destination[key_b] = torch.cat([gate_b[:orig], up_b[:orig]])

        # down_proj.weight: [hidden, padded] -> [hidden, orig]
        key_dw = prefix + "down_proj.weight"
        if key_dw in destination:
            destination[key_dw] = destination[key_dw][:, :orig]

    def _activation_chunk(self, gate_out, up_out):
        # gate_out / up_out are precomputed GEMM results
        """Activation chunk."""
        if self.hidden_act == "silu":
            out = swiglu(gate_out, up_out)
        else:
            out = self.act_fn(gate_out) * up_out
        return out

    def forward(self, hidden_state):
        # -----------------------------
        # 1. Precompute GEMM without checkpointing
        # -----------------------------
        """Run the forward pass."""
        gate_up_out = self.gate_up_proj(hidden_state)
        gate_out, up_out = gate_up_out.split(
            [self.padded_intermediate_size, self.padded_intermediate_size], dim=-1
        )

        if self.use_selective_recompute:
            # checkpoint only activation, not GEMM
            out = cp.checkpoint(
                self._activation_chunk, gate_out, up_out, use_reentrant=False
            )
        else:
            out = self._activation_chunk(gate_out, up_out)

        return self.down_proj(out)


class Qwen25VisionPatchEmbed(nn.Module):
    """Qwen2 5 VisionPatchEmbed."""
    def __init__(
        self,
        patch_size: int = 14,
        temporal_patch_size: int = 2,
        in_channels: int = 3,
        embed_dim: int = 1152,
    ) -> None:
        """Initialize the instance."""
        super().__init__()
        self.patch_size = patch_size
        self.temporal_patch_size = temporal_patch_size
        self.in_channels = in_channels
        self.embed_dim = embed_dim

        kernel_size = [temporal_patch_size, patch_size, patch_size]
        self.proj = nn.Conv3d(
            in_channels,
            embed_dim,
            kernel_size=kernel_size,
            stride=kernel_size,
            bias=False,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """Run the forward pass."""
        target_dtype = self.proj.weight.dtype
        hidden_states = hidden_states.view(
            -1,
            self.in_channels,
            self.temporal_patch_size,
            self.patch_size,
            self.patch_size,
        )
        # hidden_states = self.proj(hidden_states.to(dtype=target_dtype)).view(
        #     -1, self.embed_dim
        # )
        weight = self.proj.weight.view(self.embed_dim, -1)
        out = hidden_states.view(
            -1,
            self.in_channels
            * self.temporal_patch_size
            * self.patch_size
            * self.patch_size,
        )
        hidden_states = F.linear(out.to(target_dtype), weight)
        return hidden_states


class Qwen25VisionRotaryEmbedding(nn.Module):
    """Qwen2 5 VisionRotaryEmbedding."""
    def __init__(self, dim: int, theta: float = 10000.0) -> None:
        """Initialize the instance."""
        super().__init__()
        inv_freq = 1.0 / (theta ** (torch.arange(0, dim, 2, dtype=torch.float) / dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def forward(self, seqlen: int) -> torch.Tensor:
        """Run the forward pass."""
        seq = torch.arange(
            seqlen, device=self.inv_freq.device, dtype=self.inv_freq.dtype
        )
        freqs = torch.outer(seq, self.inv_freq)
        return freqs


class Qwen2RMSNorm(nn.Module):
    """Qwen2RMSNorm."""
    def __init__(
        self, hidden_size: int, eps: float = 1e-6, cond_dim: Optional[int] = None
    ):
        """
        Qwen2RMSNorm with optional conditional input support, equivalent to T5LayerNorm
        """
        super().__init__()
        self.variance_epsilon = eps
        self.hidden_size = hidden_size
        self.cond_dim = cond_dim

        # Dense layer for adaptive normalization (if cond_dim is provided)
        if cond_dim is not None:
            self.dense = nn.Linear(cond_dim, hidden_size * 3, bias=True)
            nn.init.zeros_(self.dense.weight)
        else:
            self.dense = None
            self.weight = nn.Parameter(torch.ones(hidden_size))

    def _norm(self, x):
        # Compute variance in float32 for numerical stability
        """Norm."""
        variance = x.pow(2).mean(-1, keepdim=True)
        # Compute normalization
        normed_inputs = x * torch.rsqrt(variance + self.variance_epsilon)
        return normed_inputs

    def forward(self, hidden_states, cond=None):
        """Run the forward pass."""
        if cond is None or self.dense is None:
            # Regular RMSNorm; the fused kernel is bitwise-identical to the
            # PyTorch path and falls back per call for unsupported inputs.
            out = rmsnorm(hidden_states, self.weight, self.variance_epsilon)
            return out, None

        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        normed_inputs = self._norm(hidden_states)

        # Adaptive RMSNorm
        if cond.shape[-1] != self.cond_dim:
            raise ValueError(
                f"Expected cond dimension {self.cond_dim}, got {cond.shape[-1]}"
            )

        # Compute modulation parameters
        cond = cond.to(dtype=self.dense.weight.dtype)
        modulation = self.dense(cond)
        if len(hidden_states.shape) == 3:  # [batch, seq, features]
            modulation = modulation.unsqueeze(1)

        scale, shift, gate = torch.chunk(modulation, 3, dim=-1)

        # Apply adaptive normalization
        normed_inputs = normed_inputs * (1 + scale.to(torch.float32)) + shift.to(
            torch.float32
        )

        return normed_inputs.to(input_dtype), gate.to(input_dtype)

    def extra_repr(self):
        """Extra repr."""
        repr_str = f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"
        if self.dense is not None:
            repr_str += f", adaptive=True, cond_dim={self.cond_dim}"
        return repr_str


class Qwen25VLPatchMerger(nn.Module):
    """Qwen2 5 VLPatchMerger."""
    def __init__(self, dim: int, context_dim: int, spatial_merge_size: int = 2) -> None:
        """Initialize the instance."""
        super().__init__()
        self.hidden_size = context_dim * (spatial_merge_size**2)
        self.ln_q = Qwen2RMSNorm(context_dim, eps=1e-6)
        self.mlp = nn.Sequential(
            nn.Linear(self.hidden_size, self.hidden_size),
            nn.GELU(),
            nn.Linear(self.hidden_size, dim),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """Run the forward pass."""
        normed_x, _ = self.ln_q(x)
        x = self.mlp(normed_x.view(-1, self.hidden_size))
        return x


def apply_rotary_pos_emb_flashatt(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> Tuple[torch.Tensor, torch.Tensor]:
    """Apply rotary pos emb flashatt."""
    cos = cos.chunk(2, dim=-1)[0].contiguous()
    sin = sin.chunk(2, dim=-1)[0].contiguous()
    q_embed = apply_rotary_emb(q.float(), cos, sin).type_as(q)
    k_embed = apply_rotary_emb(k.float(), cos, sin).type_as(k)
    return q_embed, k_embed


class Qwen25VLVisionFlashAttention2(nn.Module):
    """Qwen2 5 VLVisionFlashAttention2."""
    def __init__(self, config: Qwen25VLConfig, dim: int, num_heads: int = 16) -> None:
        """Initialize the instance."""
        super().__init__()
        self.num_heads = num_heads
        self.qkv = nn.Linear(dim, dim * 3, bias=True)
        self.proj = nn.Linear(dim, dim)
        self.deterministic = config.attn_deterministic

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        max_seqlen: Optional[int] = None,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
    ) -> torch.Tensor:
        """Run the forward pass."""
        seq_length = hidden_states.shape[0]
        q, k, v = (
            self.qkv(hidden_states)
            .reshape(seq_length, 3, self.num_heads, -1)
            .permute(1, 0, 2, 3)
            .unbind(0)
        )
        if position_embeddings is None:
            logger.warning_once(
                "The attention layers in this model are transitioning from computing the RoPE embeddings internally "
                "through `rotary_pos_emb` (2D tensor of RoPE theta values), to using externally computed "
                "`position_embeddings` (Tuple of tensors, containing cos and sin). In v4.54 `rotary_pos_emb` will be "
                "removed and `position_embeddings` will be mandatory."
            )
            emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
            cos = emb.cos().float()
            sin = emb.sin().float()
        else:
            cos, sin = position_embeddings
        q, k = apply_rotary_pos_emb_flashatt(q.unsqueeze(0), k.unsqueeze(0), cos, sin)
        q = q.squeeze(0)
        k = k.squeeze(0)

        if max_seqlen is None:
            max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max().item()
        attn_output = flash_attn_varlen_func(
            q,
            k,
            v,
            cu_seqlens,
            cu_seqlens,
            max_seqlen,
            max_seqlen,
            deterministic=self.deterministic,
        ).reshape(seq_length, -1)
        attn_output = self.proj(attn_output)
        return attn_output


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb_vision(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> Tuple[torch.Tensor, torch.Tensor]:
    """Apply rotary pos emb vision."""
    orig_q_dtype = q.dtype
    orig_k_dtype = k.dtype
    q, k = q.float(), k.float()
    cos, sin = cos.unsqueeze(-2), sin.unsqueeze(-2)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    q_embed = q_embed.to(orig_q_dtype)
    k_embed = k_embed.to(orig_k_dtype)
    return q_embed, k_embed


class Qwen25VLVisionAttention(nn.Module):
    """Qwen2 5 VLVisionAttention."""
    def __init__(self, config: Qwen25VLConfig, dim: int, num_heads: int = 16) -> None:
        """Initialize the instance."""
        super().__init__()
        self.num_heads = num_heads
        self.head_dim = dim // num_heads
        self.qkv = nn.Linear(dim, dim * 3, bias=True)
        self.proj = nn.Linear(dim, dim)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        """Run the forward pass."""
        seq_length = hidden_states.shape[0]
        q, k, v = (
            self.qkv(hidden_states)
            .reshape(seq_length, 3, self.num_heads, -1)
            .permute(1, 0, 2, 3)
            .unbind(0)
        )
        if position_embeddings is None:
            logger.warning_once(
                "The attention layers in this model are transitioning from computing the RoPE embeddings internally "
                "through `rotary_pos_emb` (2D tensor of RoPE theta values), to using externally computed "
                "`position_embeddings` (Tuple of tensors, containing cos and sin). In v4.54 `rotary_pos_emb` will be "
                "removed and `position_embeddings` will be mandatory."
            )
            emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
            cos = emb.cos().float()
            sin = emb.sin().float()
        else:
            cos, sin = position_embeddings
        q, k = apply_rotary_pos_emb_vision(q, k, cos, sin)

        attention_mask = torch.full(
            [1, seq_length, seq_length],
            torch.finfo(q.dtype).min,
            device=q.device,
            dtype=q.dtype,
        )
        for i in range(1, len(cu_seqlens)):
            attention_mask[
                ...,
                cu_seqlens[i - 1] : cu_seqlens[i],
                cu_seqlens[i - 1] : cu_seqlens[i],
            ] = 0

        q = q.transpose(0, 1)
        k = k.transpose(0, 1)
        v = v.transpose(0, 1)
        attn_weights = torch.matmul(q, k.transpose(1, 2)) / math.sqrt(self.head_dim)
        attn_weights = attn_weights + attention_mask
        attn_weights = nn.functional.softmax(
            attn_weights, dim=-1, dtype=torch.float32
        ).to(q.dtype)
        attn_output = torch.matmul(attn_weights, v)
        attn_output = attn_output.transpose(0, 1)
        attn_output = attn_output.reshape(seq_length, -1)
        attn_output = self.proj(attn_output)
        return attn_output


class Qwen25VLVisionSdpaAttention(nn.Module):
    """Qwen2 5 VLVisionSdpaAttention."""
    def __init__(self, config: Qwen25VLConfig, dim: int, num_heads: int = 16) -> None:
        """Initialize the instance."""
        super().__init__()
        self.num_heads = num_heads
        self.qkv = nn.Linear(dim, dim * 3, bias=True)
        self.proj = nn.Linear(dim, dim)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        """Run the forward pass."""
        seq_length = hidden_states.shape[0]
        q, k, v = (
            self.qkv(hidden_states)
            .reshape(seq_length, 3, self.num_heads, -1)
            .permute(1, 0, 2, 3)
            .unbind(0)
        )
        if position_embeddings is None:
            logger.warning_once(
                "The attention layers in this model are transitioning from computing the RoPE embeddings internally "
                "through `rotary_pos_emb` (2D tensor of RoPE theta values), to using externally computed "
                "`position_embeddings` (Tuple of tensors, containing cos and sin). In v4.54 `rotary_pos_emb` will be "
                "removed and `position_embeddings` will be mandatory."
            )
            emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
            cos = emb.cos().float()
            sin = emb.sin().float()
        else:
            cos, sin = position_embeddings
        q, k = apply_rotary_pos_emb_vision(q, k, cos, sin)

        attention_mask = torch.zeros(
            [1, seq_length, seq_length], device=q.device, dtype=torch.bool
        )
        for i in range(1, len(cu_seqlens)):
            attention_mask[
                ...,
                cu_seqlens[i - 1] : cu_seqlens[i],
                cu_seqlens[i - 1] : cu_seqlens[i],
            ] = True
        q = q.transpose(0, 1)
        k = k.transpose(0, 1)
        v = v.transpose(0, 1)
        attn_output = F.scaled_dot_product_attention(
            q, k, v, attention_mask, dropout_p=0.0
        )
        attn_output = attn_output.transpose(0, 1)
        attn_output = attn_output.reshape(seq_length, -1)
        attn_output = self.proj(attn_output)
        return attn_output


QWEN2_5_VL_VISION_ATTENTION_CLASSES = {
    "eager": Qwen25VLVisionAttention,
    "flash_attention_2": Qwen25VLVisionFlashAttention2,
    "sdpa": Qwen25VLVisionSdpaAttention,
}


class Qwen25VLVisionBlock(nn.Module):
    """Qwen2 5 VLVisionBlock."""
    def __init__(
        self,
        config,
        attn_implementation: str = "sdpa",
        use_selective_recompute: bool = False,
    ):
        """Initialize the instance."""
        super().__init__()
        self.use_selective_recompute = use_selective_recompute

        self.norm1 = Qwen2RMSNorm(config.hidden_size, eps=1e-6)
        self.norm2 = Qwen2RMSNorm(config.hidden_size, eps=1e-6)

        self.attn = QWEN2_5_VL_VISION_ATTENTION_CLASSES[attn_implementation](
            config, config.hidden_size, num_heads=config.num_heads
        )
        self.mlp = Qwen25VLMLP(
            config, bias=True, use_selective_recompute=use_selective_recompute
        )

    # -----------------------------
    # selective checkpoint for norm
    # -----------------------------
    def _norm1_chunk(self, hidden_states):
        """Norm1 chunk."""
        return self.norm1(hidden_states)[0]  # return only normed_hidden_states

    def _norm2_chunk(self, hidden_states):
        """Norm2 chunk."""
        return self.norm2(hidden_states)[0]

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        max_seqlen: Optional[int] = None,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
    ) -> torch.Tensor:

        # ============================
        # 1) Norm1 with checkpoint
        # ============================
        """Run the forward pass."""
        if self.use_selective_recompute:
            normed_hidden_states = cp.checkpoint(
                self._norm1_chunk,
                hidden_states,
                use_reentrant=False,
            )
            # residual RMS is not used by subsequent computation and is usually unused in large-model training
            _ = None
        else:
            normed_hidden_states, _ = self.norm1(hidden_states)

        # Attention does not recompute GEMM
        hidden_states = hidden_states + self.attn(
            normed_hidden_states,
            cu_seqlens=cu_seqlens,
            max_seqlen=max_seqlen,
            rotary_pos_emb=rotary_pos_emb,
            position_embeddings=position_embeddings,
        )

        # ============================
        # 2) Norm2 with checkpoint
        # ============================
        if self.use_selective_recompute:
            normed_hidden_states = cp.checkpoint(
                self._norm2_chunk,
                hidden_states,
                use_reentrant=False,
            )
            _ = None
        else:
            normed_hidden_states, _ = self.norm2(hidden_states)

        # MLP only recomputes the hooked activation and does not recompute GEMM
        hidden_states = hidden_states + self.mlp(normed_hidden_states)

        return hidden_states


Qwen2_5_VL_START_DOCSTRING = r"""
    This model inherits from [`PreTrainedModel`]. Check the superclass documentation for the generic methods the
    library implements for all its model (such as downloading or saving, resizing the input embeddings, pruning heads
    etc.)

    This model is also a PyTorch [torch.nn.Module](https://pytorch.org/docs/stable/nn.html#torch.nn.Module) subclass.
    Use it as a regular PyTorch Module and refer to the PyTorch documentation for all matter related to general usage
    and behavior.

    Parameters:
        config ([`Qwen25VLConfig`]):
            Model configuration class with all the parameters of the model. Initializing with a config file does not
            load the weights associated with the model, only the configuration. Check out the
            [`~PreTrainedModel.from_pretrained`] method to load the model weights.
"""


@add_start_docstrings(
    "The bare Qwen2_5_VL Model outputting raw hidden-states without any specific head on top.",
    Qwen2_5_VL_START_DOCSTRING,
)
class Qwen25VLPreTrainedModel(AttentionsSelectorMixin, PreTrainedModel):
    """Qwen2 5 VLPreTrainedModel."""
    config_class = Qwen25VLConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["Qwen25VLVisionBlock"]
    _skip_keys_device_placement = "past_key_values"
    _supports_flash_attn_2 = True
    _supports_sdpa = True
    _supports_cache_class = True
    _supports_static_cache = False  # TODO (joao): fix. torch.compile failing probably due to `cache_positions`

    def _init_weights(self, module):
        """Init weights."""
        std = self.config.initializer_range
        if isinstance(module, (nn.Linear, nn.Conv3d)):
            module.weight.data.normal_(mean=0.0, std=std)
            if module.bias is not None:
                module.bias.data.zero_()
        elif isinstance(module, nn.Embedding):
            module.weight.data.normal_(mean=0.0, std=std)
            if module.padding_idx is not None:
                module.weight.data[module.padding_idx].zero_()


class Qwen25VisionTransformerPretrainedModel(Qwen25VLPreTrainedModel):
    """Qwen2 5 VisionTransformerPretrainedModel."""
    config_class = Qwen25VLVisionConfig
    _no_split_modules = ["Qwen25VLVisionBlock"]

    def __init__(
        self, config, use_selective_recompute=False, *inputs, **kwargs
    ) -> None:
        """Initialize the instance."""
        super().__init__(config, *inputs, **kwargs)
        self.use_selective_recompute = use_selective_recompute
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.fullatt_block_indexes = config.fullatt_block_indexes
        self.window_size = config.window_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen25VisionPatchEmbed(
            patch_size=config.patch_size,
            temporal_patch_size=config.temporal_patch_size,
            in_channels=config.in_channels,
            embed_dim=config.hidden_size,
        )

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen25VisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList(
            [
                Qwen25VLVisionBlock(
                    config, config._attn_implementation, use_selective_recompute
                )
                for _ in range(config.depth)
            ]
        )
        self.merger = Qwen25VLPatchMerger(
            dim=config.out_hidden_size,
            context_dim=config.hidden_size,
            spatial_merge_size=config.spatial_merge_size,
        )
        self.gradient_checkpointing = False

    def rot_pos_emb(self, grid_thw):
        """Rot pos emb."""
        pos_ids = []
        for t, h, w in grid_thw:
            hpos_ids = torch.arange(h).unsqueeze(1).expand(-1, w)
            hpos_ids = hpos_ids.reshape(
                h // self.spatial_merge_size,
                self.spatial_merge_size,
                w // self.spatial_merge_size,
                self.spatial_merge_size,
            )
            hpos_ids = hpos_ids.permute(0, 2, 1, 3)
            hpos_ids = hpos_ids.flatten()

            wpos_ids = torch.arange(w).unsqueeze(0).expand(h, -1)
            wpos_ids = wpos_ids.reshape(
                h // self.spatial_merge_size,
                self.spatial_merge_size,
                w // self.spatial_merge_size,
                self.spatial_merge_size,
            )
            wpos_ids = wpos_ids.permute(0, 2, 1, 3)
            wpos_ids = wpos_ids.flatten()
            pos_ids.append(torch.stack([hpos_ids, wpos_ids], dim=-1).repeat(t, 1))
        pos_ids = torch.cat(pos_ids, dim=0)
        max_grid_size = grid_thw[:, 1:].max()
        rotary_pos_emb_full = self.rotary_pos_emb(max_grid_size)
        rotary_pos_emb = rotary_pos_emb_full[pos_ids].flatten(1)
        return rotary_pos_emb

    def get_window_index(self, grid_thw):
        """Get window index."""
        window_index: list = []
        cu_window_seqlens: list = [0]
        window_index_id = 0
        vit_merger_window_size = (
            self.window_size // self.spatial_merge_size // self.patch_size
        )

        for grid_t, grid_h, grid_w in grid_thw:
            llm_grid_h, llm_grid_w = (
                grid_h // self.spatial_merge_size,
                grid_w // self.spatial_merge_size,
            )
            index = torch.arange(grid_t * llm_grid_h * llm_grid_w).reshape(
                grid_t, llm_grid_h, llm_grid_w
            )
            pad_h = vit_merger_window_size - llm_grid_h % vit_merger_window_size
            pad_w = vit_merger_window_size - llm_grid_w % vit_merger_window_size
            num_windows_h = (llm_grid_h + pad_h) // vit_merger_window_size
            num_windows_w = (llm_grid_w + pad_w) // vit_merger_window_size
            index_padded = F.pad(index, (0, pad_w, 0, pad_h), "constant", -100)
            index_padded = index_padded.reshape(
                grid_t,
                num_windows_h,
                vit_merger_window_size,
                num_windows_w,
                vit_merger_window_size,
            )
            index_padded = index_padded.permute(0, 1, 3, 2, 4).reshape(
                grid_t,
                num_windows_h * num_windows_w,
                vit_merger_window_size,
                vit_merger_window_size,
            )
            seqlens = (index_padded != -100).sum([2, 3]).reshape(-1)
            index_padded = index_padded.reshape(-1)
            index_new = index_padded[index_padded != -100]
            window_index.append(index_new + window_index_id)
            cu_seqlens_tmp = (
                seqlens.cumsum(0) * self.spatial_merge_unit + cu_window_seqlens[-1]
            )
            cu_window_seqlens.extend(cu_seqlens_tmp.tolist())
            window_index_id += (grid_t * llm_grid_h * llm_grid_w).item()
        window_index = torch.cat(window_index, dim=0)

        return window_index, cu_window_seqlens

    def forward(
        self,
        hidden_states: torch.Tensor,
        grid_thw: torch.Tensor,
        vision_grid_metadata=None,
    ) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.

        Returns:
            `torch.Tensor`: hidden_states.
        """
        hidden_states = self.patch_embed(hidden_states)
        rotary_pos_emb = rot_pos_emb(
            self.rotary_pos_emb.inv_freq.to(torch.float32),
            grid_thw,
            self.spatial_merge_size,
            metadata=vision_grid_metadata,
        )
        window_index, cu_window_seqlens = get_window_index(
            grid_thw=grid_thw.to(torch.int32),
            window_size=self.window_size,
            spatial_merge_size=self.spatial_merge_size,
            patch_size=self.patch_size,
            spatial_merge_unit=self.spatial_merge_unit,
            metadata=vision_grid_metadata,
        )

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(
            seq_len // self.spatial_merge_unit, self.spatial_merge_unit, -1
        )
        hidden_states = hidden_states[window_index, :, :]
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(
            seq_len // self.spatial_merge_unit, self.spatial_merge_unit, -1
        )
        rotary_pos_emb = rotary_pos_emb[window_index, :, :]
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)
        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        repeat_interleave_kwargs = {}
        if vision_grid_metadata is not None:
            repeat_interleave_kwargs["output_size"] = vision_grid_metadata.total_grid_t
        cu_seqlens = torch.repeat_interleave(
            grid_thw[:, 1] * grid_thw[:, 2],
            grid_thw[:, 0],
            **repeat_interleave_kwargs,
        ).cumsum(
            dim=0,
            # Select dtype based on the following factors:
            #  - FA2 requires that cu_seqlens_q must have dtype int32
            #  - torch.onnx.export requires that cu_seqlens_q must have same dtype as grid_thw
            # See https://github.com/huggingface/transformers/pull/34852 for more information
            dtype=grid_thw.dtype if torch.jit.is_tracing() else torch.int32,
        )
        cu_seqlens = F.pad(cu_seqlens, (1, 0), value=0)
        if vision_grid_metadata is None:
            max_seqlen_full = (cu_seqlens[1:] - cu_seqlens[:-1]).max().item()
            max_seqlen_window = (
                (cu_window_seqlens[1:] - cu_window_seqlens[:-1]).max().item()
            )
        else:
            max_seqlen_full = vision_grid_metadata.max_seqlen_full
            max_seqlen_window = vision_grid_metadata.max_seqlen_window

        for layer_num, blk in enumerate(self.blocks):
            if layer_num in self.fullatt_block_indexes:
                cu_seqlens_now = cu_seqlens
                max_seqlen_now = max_seqlen_full
            else:
                cu_seqlens_now = cu_window_seqlens
                max_seqlen_now = max_seqlen_window
            if self.gradient_checkpointing and self.training:
                hidden_states = self._gradient_checkpointing_func(
                    blk.__call__,
                    hidden_states,
                    cu_seqlens=cu_seqlens_now,
                    max_seqlen=max_seqlen_now,
                    position_embeddings=position_embeddings,
                )
            else:
                hidden_states = blk(
                    hidden_states,
                    cu_seqlens=cu_seqlens_now,
                    max_seqlen=max_seqlen_now,
                    position_embeddings=position_embeddings,
                )

        hidden_states = self.merger(hidden_states)
        reverse_indices = torch.argsort(window_index)
        hidden_states = hidden_states[reverse_indices, :]

        return hidden_states


class Qwen25VLRotaryEmbedding(nn.Module):
    """Qwen2 5 VLRotaryEmbedding."""
    def __init__(self, config: Qwen25VLConfig, device=None):
        """Initialize the instance."""
        super().__init__()
        # BC: "rope_type" was originally "type"
        if hasattr(config, "rope_scaling") and config.rope_scaling is not None:
            self.rope_type = config.rope_scaling.get(
                "rope_type", config.rope_scaling.get("type", "default")
            )
        else:
            self.rope_type = "default"
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config

        # Compatibility with newer transformers versions (5.x):
        # Newer versions remove the "default" key from ROPE_INIT_FUNCTIONS and compute default RoPE inline.
        # Older versions (4.x): ROPE_INIT_FUNCTIONS["default"] exists and can be used normally.
        # Newer versions (5.x): when rope_type=="default", use compute_default_rope_parameters instead.
        if self.rope_type == "default":
            self.rope_init_fn = self.compute_default_rope_parameters
        else:
            self.rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]

        inv_freq, self.attention_scaling = self.rope_init_fn(self.config, device)
        self.register_buffer("inv_freq", inv_freq, persistent=False)
        self.original_inv_freq = self.inv_freq

    @staticmethod
    def compute_default_rope_parameters(
        config: Qwen25VLConfig,
        device=None,
        seq_len=None,
    ):
        """Compute default RoPE parameters, matching older ROPE_INIT_FUNCTIONS["default"].
        Transformers 5.x moved this logic out of ROPE_INIT_FUNCTIONS and into the model class.
        """
        base = config.rope_theta
        dim = config.hidden_size // config.num_attention_heads
        attention_factor = 1.0
        inv_freq = 1.0 / (
            base
            ** (
                torch.arange(0, dim, 2, dtype=torch.int64).to(
                    device=device, dtype=torch.float
                )
                / dim
            )
        )
        return inv_freq, attention_factor

    def _dynamic_frequency_update(self, position_ids, device):
        """
        dynamic RoPE layers should recompute `inv_freq` in the following situations:
        1 - growing beyond the cached sequence length (allow scaling)
        2 - the current sequence length is in the original scale (avoid losing precision with small sequences)
        """
        seq_len = torch.max(position_ids) + 1
        if seq_len > self.max_seq_len_cached:  # growth
            inv_freq, self.attention_scaling = self.rope_init_fn(
                self.config, device, seq_len=seq_len, **self.rope_kwargs
            )
            self.register_buffer(
                "inv_freq", inv_freq, persistent=False
            )  # TODO joao: may break with compilation
            self.max_seq_len_cached = seq_len

        if (
            seq_len < self.original_max_seq_len
            and self.max_seq_len_cached > self.original_max_seq_len
        ):  # reset
            self.register_buffer("inv_freq", self.original_inv_freq, persistent=False)
            self.max_seq_len_cached = self.original_max_seq_len

    @torch.no_grad()
    def forward(self, x, position_ids):
        """Run the forward pass."""
        if "dynamic" in self.rope_type:
            self._dynamic_frequency_update(position_ids, device=x.device)

        # Core RoPE block. In contrast to other models, Qwen2_5_VL has different position ids for thw grids
        # So we expand the inv_freq to shape (3, ...)
        inv_freq_expanded = (
            self.inv_freq[None, None, :, None]
            .float()
            .expand(3, position_ids.shape[1], -1, 1)
        )
        position_ids_expanded = position_ids[
            :, :, None, :
        ].float()  # shape (3, bs, 1, positions)
        # Force float32 (see https://github.com/huggingface/transformers/pull/29285)
        device_type = x.device.type
        device_type = (
            device_type
            if isinstance(device_type, str) and device_type != "mps"
            else "cpu"
        )
        with torch.autocast(device_type=device_type, enabled=False):
            freqs = (
                inv_freq_expanded.float() @ position_ids_expanded.float()
            ).transpose(2, 3)
            emb = torch.cat((freqs, freqs), dim=-1)
            cos = emb.cos()
            sin = emb.sin()

        # Advanced RoPE types (e.g. yarn) apply a post-processing scaling factor, equivalent to scaling attention
        cos = cos * self.attention_scaling
        sin = sin * self.attention_scaling

        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)


class Qwen2MLP(nn.Module):
    """Qwen2MLP."""
    def __init__(self, config):
        """Initialize the instance."""
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.gate_up_proj = nn.Linear(
            self.hidden_size, 2 * self.intermediate_size, bias=False
        )
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.hidden_act = config.hidden_act
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        """Run the forward pass."""
        gate_up_out = self.gate_up_proj(x)
        gate_out, up_out = gate_up_out.split(
            [self.intermediate_size, self.intermediate_size], dim=-1
        )
        if self.hidden_act == "silu":
            act_out = swiglu(gate_out, up_out)
        else:
            act_out = self.act_fn(gate_out) * up_out
        down_proj = self.down_proj(act_out)
        return down_proj


def apply_multimodal_rotary_pos_emb(q, k, cos, sin, mrope_section, unsqueeze_dim=1):
    """Applies Rotary Position Embedding with Multimodal Sections to the query and key tensors
    (https://qwenlm.github.io/blog/qwen2-vl/).

    Explanation:
        Multimodal 3D rotary position embedding is an extension to 1D rotary position embedding. The input embedding
        sequence contains vision (images / videos) embedding and text embedding or just contains text embedding. For
        vision embedding part, we apply rotary position embedding on temporal, height and width dimension seperately.
        Here we split the channel dimension to 3 chunks for the temporal, height and width rotary position embedding.
        For text embedding part, we just apply 1D rotary position embedding. The three rotary position index (temporal,
        height and width) of text embedding is always the same, so the text embedding rotary position embedding has no
        difference with modern LLMs.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        position_ids (`torch.Tensor`):
            The position indices of the tokens corresponding to the query and key tensors. For example, this can be
            used to pass offsetted position ids when working with a KV-cache.
        mrope_section(`List(int)`):
            Multimodal rope section is for channel dimension of temporal, height and width in rope calculation.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    mrope_section = mrope_section * 2
    cos = torch.cat(
        [m[i % 3] for i, m in enumerate(cos.split(mrope_section, dim=-1))], dim=-1
    ).unsqueeze(unsqueeze_dim)
    sin = torch.cat(
        [m[i % 3] for i, m in enumerate(sin.split(mrope_section, dim=-1))], dim=-1
    ).unsqueeze(unsqueeze_dim)

    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(
        batch, num_key_value_heads, n_rep, slen, head_dim
    )
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


class Qwen25VLAttention(nn.Module):
    """
    Multi-headed attention from 'Attention Is All You Need' paper. Modified to use sliding window attention: Longformer
    and "Generating Long Sequences with Sparse Transformers".
    """

    def __init__(self, config: Qwen25VLConfig, layer_idx: Optional[int] = None):
        """Initialize the instance."""
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        if layer_idx is None:
            logger.warning_once(
                f"Instantiating {self.__class__.__name__} without passing `layer_idx` is not recommended and will "
                "to errors during the forward call, if caching is used. Please make sure to provide a `layer_idx` "
                "when creating this class."
            )

        self.hidden_size = config.hidden_size
        self.num_heads = config.num_attention_heads
        self.head_dim = self.hidden_size // self.num_heads
        self.num_key_value_heads = config.num_key_value_heads
        self.num_key_value_groups = self.num_heads // self.num_key_value_heads
        self.is_causal = True
        self.attention_dropout = config.attention_dropout
        self.rope_scaling = config.rope_scaling

        if (self.head_dim * self.num_heads) != self.hidden_size:
            raise ValueError(
                f"hidden_size must be divisible by num_heads (got `hidden_size`: {self.hidden_size}"
                f" and `num_heads`: {self.num_heads})."
            )

        qkv_dim = (
            self.num_heads * self.head_dim
            + 2 * self.num_key_value_heads * self.head_dim
        )
        self.qkv_proj = nn.Linear(self.hidden_size, qkv_dim, bias=True)

        self.o_proj = nn.Linear(
            self.num_heads * self.head_dim, self.hidden_size, bias=False
        )

        self.rotary_emb = Qwen25VLRotaryEmbedding(config=config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_value: Optional[Cache] = None,
        output_attentions: bool = False,
        use_cache: bool = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[
            Tuple[torch.Tensor, torch.Tensor]
        ] = None,  # necessary, but kept here for BC
        **kwargs,
    ) -> Tuple[torch.Tensor, Optional[torch.Tensor], Optional[Tuple[torch.Tensor]]]:
        """Run the forward pass."""
        bsz, q_len, _ = hidden_states.size()

        qkv = self.qkv_proj(hidden_states)  # [bsz, q_len, q_dim + 2 * kv_dim]
        kv_dim = self.num_key_value_heads * self.head_dim
        q, k, v = torch.split(
            qkv, [self.num_heads * self.head_dim, kv_dim, kv_dim], dim=-1
        )
        query_states = q.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = k.view(
            bsz, q_len, self.num_key_value_heads, self.head_dim
        ).transpose(1, 2)
        value_states = v.view(
            bsz, q_len, self.num_key_value_heads, self.head_dim
        ).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_multimodal_rotary_pos_emb(
            query_states, key_states, cos, sin, self.rope_scaling["mrope_section"]
        )

        if past_key_value is not None:
            cache_kwargs = {
                "sin": sin,
                "cos": cos,
                "cache_position": cache_position,
            }  # Specific to RoPE models
            key_states, value_states = past_key_value.update(
                key_states, value_states, self.layer_idx, cache_kwargs
            )

        # repeat k/v heads if n_kv_heads < n_heads
        key_states = repeat_kv(key_states, self.num_key_value_groups)
        value_states = repeat_kv(value_states, self.num_key_value_groups)

        attn_weights = torch.matmul(
            query_states, key_states.transpose(2, 3)
        ) / math.sqrt(self.head_dim)

        if attention_mask is not None:  # no matter the length, we just slice it
            causal_mask = attention_mask[:, :, :, : key_states.shape[-2]]
            attn_weights = attn_weights + causal_mask

        # Fix precision issues in Qwen2-VL float16 inference
        # Replace inf values with zeros in attention weights to prevent NaN propagation
        if query_states.dtype == torch.float16:
            attn_weights = torch.where(
                torch.isinf(attn_weights), torch.zeros_like(attn_weights), attn_weights
            )

        # upcast attention to fp32
        attn_weights = nn.functional.softmax(
            attn_weights, dim=-1, dtype=torch.float32
        ).to(query_states.dtype)
        attn_weights = nn.functional.dropout(
            attn_weights, p=self.attention_dropout, training=self.training
        )
        attn_output = torch.matmul(attn_weights, value_states)

        if attn_output.size() != (bsz, self.num_heads, q_len, self.head_dim):
            raise ValueError(
                f"`attn_output` should be of size {(bsz, self.num_heads, q_len, self.head_dim)}, but is"
                f" {attn_output.size()}"
            )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, -1)

        attn_output = self.o_proj(attn_output)

        if not output_attentions:
            attn_weights = None

        return attn_output, attn_weights, past_key_value


class Qwen25VLFlashAttention2(Qwen25VLAttention):
    """
    Qwen2_5_VL flash attention module, following Qwen2_5_VL attention module. This module inherits from
    `Qwen25VLAttention`
    as the weights of the module stays untouched. The only required change would be on the forward pass
    where it needs to correctly call the public API of flash attention and deal with padding tokens
    in case the input contains any of them. Additionally, for sliding window attention, we apply SWA only to the bottom
    config.max_window_layers layers.
    """

    def __init__(self, config: Qwen25VLConfig, layer_idx: Optional[int] = None):
        """Initialize the instance."""
        super().__init__(config, layer_idx)

        # TODO: Should be removed once Flash Attention for RoCm is bumped to 2.1.
        # flash_attn<2.1 generates top-left aligned causal mask, while what is needed here is bottom-right alignement,
        # that was made default for flash_attn>=2.1. This attribute is used to handle this difference. Reference:
        # https://github.com/Dao-AILab/flash-attention/releases/tag/v2.1.0.
        # Beware that with flash_attn<2.1, using q_seqlen != k_seqlen (except for the case q_seqlen == 1) produces a
        # wrong mask (top-left).
        self._flash_attn_uses_top_left_mask = not is_flash_attn_greater_or_equal_2_10()
        self.deterministic = config.attn_deterministic

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_value: Optional[Cache] = None,
        output_attentions: bool = False,
        use_cache: bool = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[
            Tuple[torch.Tensor, torch.Tensor]
        ] = None,  # necessary, but kept here for BC
    ):
        """Run the forward pass."""
        bsz, q_len, _ = hidden_states.size()

        qkv = self.qkv_proj(hidden_states)  # [bsz, q_len, q_dim + 2 * kv_dim]
        kv_dim = self.num_key_value_heads * self.head_dim
        q, k, v = torch.split(
            qkv, [self.num_heads * self.head_dim, kv_dim, kv_dim], dim=-1
        )

        query_states = q.view(bsz, q_len, self.num_heads, self.head_dim)
        key_states = k.view(bsz, q_len, self.num_key_value_heads, self.head_dim)
        value_states = v.view(bsz, q_len, self.num_key_value_heads, self.head_dim)

        # Because the input can be padded, the absolute sequence length depends on the max position id.
        cos, sin = position_embeddings

        query_states, key_states = m_rope(
            query_states.contiguous(),
            key_states.contiguous(),
            cos[..., : (cos.size(-1) // 2)].contiguous().float(),
            sin[..., : (sin.size(-1) // 2)].contiguous().float(),
            self.rope_scaling["mrope_section"],
        )
        if past_key_value is not None:
            cache_kwargs = {
                "sin": sin,
                "cos": cos,
                "cache_position": cache_position,
            }  # Specific to RoPE models
            key_states, value_states = past_key_value.update(
                key_states.transpose(1, 2),
                value_states.transpose(1, 2),
                self.layer_idx,
                cache_kwargs,
            )
            key_states, value_states = key_states.transpose(
                1, 2
            ), value_states.transpose(1, 2)

        # repeat k/v heads if n_kv_heads < n_heads
        # key_states = repeat_kv(key_states, self.num_key_value_groups)
        # value_states = repeat_kv(value_states, self.num_key_value_groups)
        dropout_rate = 0.0 if not self.training else self.attention_dropout

        # In PEFT, usually we cast the layer norms in float32 for training stability reasons
        # therefore the input hidden states gets silently casted in float32. Hence, we need
        # cast them back in float16 just to be sure everything works as expected.
        input_dtype = query_states.dtype
        if input_dtype == torch.float32:
            if torch.is_autocast_enabled():
                target_dtype = torch.get_autocast_gpu_dtype()
            # Handle the case where the model is quantized
            elif hasattr(self.config, "_pre_quantization_dtype"):
                target_dtype = self.config._pre_quantization_dtype
            else:
                target_dtype = self.qkv_proj.weight.dtype

            logger.warning_once(
                f"The input hidden states seems to be silently casted in float32, this might be related to"
                f" the fact you have upcasted embedding or layer norm layers in float32. We will cast back the input in"
                f" {target_dtype}."
            )

            query_states = query_states.to(target_dtype)
            key_states = key_states.to(target_dtype)
            value_states = value_states.to(target_dtype)

        attn_output = flash_attn_func(
            query_states,
            key_states,
            value_states,
            dropout_rate,
            softmax_scale=None,
            causal=self.is_causal,
            deterministic=self.deterministic,
        )

        attn_output = attn_output.reshape(bsz, q_len, self.hidden_size).contiguous()
        attn_output = self.o_proj(attn_output)

        if not output_attentions:
            attn_weights = None
        if output_attentions:
            with torch.no_grad():
                query_states = query_states.transpose(1, 2)
                key_states = key_states.transpose(1, 2)
                key_states = repeat_kv(key_states, self.num_key_value_groups)
                scale = 1.0 / torch.sqrt(
                    torch.tensor(
                        self.head_dim, device=hidden_states.device, dtype=torch.float32
                    )
                )
                attention_score = (
                    torch.matmul(query_states, key_states.transpose(-2, -1)) * scale
                )
                causal_mask_local = torch.tril(
                    torch.ones(
                        attention_score.size(-2),
                        attention_score.size(-1),
                        device=attention_score.device,
                        dtype=torch.bool,
                    )
                )
                mask = (
                    causal_mask_local.unsqueeze(0)
                    .unsqueeze(0)
                    .expand(attention_score.size(0), attention_score.size(1), -1, -1)
                )
                if mask.dtype != attention_score.dtype:
                    mask = mask.to(dtype=attention_score.dtype)
                attention_score = attention_score.masked_fill(
                    ~(mask.bool()), float("-inf")
                )
                attention_score = torch.softmax(attention_score, dim=-1)
                attn_weights = attention_score[0].mean(0)

        return attn_output, attn_weights, past_key_value


class Qwen25VLSdpaAttention(Qwen25VLAttention):
    """
    Qwen2 attention module using torch.nn.functional.scaled_dot_product_attention. This module inherits from
    `Qwen2Attention` as the weights of the module stays untouched. The only changes are on the forward pass to adapt to
    SDPA API.
    """

    # Adapted from Qwen2Attention.forward
    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_value: Optional[Cache] = None,
        output_attentions: bool = False,
        use_cache: bool = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[
            Tuple[torch.Tensor, torch.Tensor]
        ] = None,  # necessary, but kept here for BC
    ) -> Tuple[torch.Tensor, Optional[torch.Tensor], Optional[Tuple[torch.Tensor]]]:
        """Run the forward pass."""
        if output_attentions:
            # TODO: Improve this warning with e.g. `model.config.attn_implementation = "manual"` once this is
            # implemented.
            logger.warning_once(
                "This attention module is using Qwen25VLSdpaAttention, but "
                "`torch.nn.functional.scaled_dot_product_attention` does not support `output_attentions=True`. Falling "
                "back to the manual attention implementation, "
                'but specifying the manual implementation will be required from Transformers version v5.0.0 onwards. '
                'This warning can be removed using the argument `attn_implementation="eager"` when loading the model.'
            )
            return super().forward(
                hidden_states=hidden_states,
                attention_mask=attention_mask,
                position_ids=position_ids,
                past_key_value=past_key_value,
                output_attentions=output_attentions,
                use_cache=use_cache,
                cache_position=cache_position,
                position_embeddings=position_embeddings,
            )

        bsz, q_len, _ = hidden_states.size()

        qkv = self.qkv_proj(hidden_states)  # [bsz, q_len, q_dim + 2 * kv_dim]
        kv_dim = self.num_key_value_heads * self.head_dim
        q, k, v = torch.split(
            qkv, [self.num_heads * self.head_dim, kv_dim, kv_dim], dim=-1
        )
        query_states = q.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = k.view(
            bsz, q_len, self.num_key_value_heads, self.head_dim
        ).transpose(1, 2)
        value_states = v.view(
            bsz, q_len, self.num_key_value_heads, self.head_dim
        ).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_multimodal_rotary_pos_emb(
            query_states, key_states, cos, sin, self.rope_scaling["mrope_section"]
        )

        if past_key_value is not None:
            cache_kwargs = {
                "sin": sin,
                "cos": cos,
                "cache_position": cache_position,
            }  # Specific to RoPE models
            if use_cache:
                key_states, value_states = past_key_value.update(
                    key_states, value_states, self.layer_idx, cache_kwargs
                )
            else:
                # Compatible across transformers versions:
                # v5.x: DynamicCache uses .layers[idx].keys/.values
                # v4.x: DynamicCache uses .key_cache[idx]/.value_cache[idx]
                # old:  Cache object is subscriptable, returns (key, value) tuple
                if hasattr(past_key_value, "layers"):
                    past_key_states = past_key_value.layers[self.layer_idx].keys
                    past_value_states = past_key_value.layers[self.layer_idx].values
                elif hasattr(past_key_value, "key_cache"):
                    past_key_states = past_key_value.key_cache[self.layer_idx]
                    past_value_states = past_key_value.value_cache[self.layer_idx]
                else:
                    past_key_states, past_value_states = past_key_value[self.layer_idx]
                key_states = torch.cat([past_key_states, key_states], dim=-2)
                value_states = torch.cat([past_value_states, value_states], dim=-2)

        key_states = repeat_kv(key_states, self.num_key_value_groups)
        value_states = repeat_kv(value_states, self.num_key_value_groups)

        causal_mask = attention_mask
        if attention_mask is not None:  # no matter the length, we just slice it
            # Ensure attention_mask matches the head dimension
            if len(attention_mask.shape) == 2:  # [batch_size, seq_len]
                # Expand to causal mask format [batch_size, 1, seq_len, seq_len]
                bsz, seq_len = attention_mask.shape
                causal_mask = attention_mask.view(bsz, 1, 1, seq_len).expand(
                    bsz, 1, seq_len, seq_len
                )
            elif len(attention_mask.shape) == 3:  # [batch_size, seq_len, seq_len]
                # Add the head dimension: [batch_size, 1, seq_len, seq_len]
                causal_mask = attention_mask.unsqueeze(1)
            elif (
                len(attention_mask.shape) == 4
            ):  # [batch_size, num_heads, seq_len, seq_len]
                causal_mask = attention_mask
            else:
                raise ValueError(
                    f"Unsupported attention_mask shape: {attention_mask.shape}"
                )

            # Convert attention mask to bool
            causal_mask = causal_mask.to(torch.bool)

        # SDPA with memory-efficient backend is currently (torch==2.1.2) bugged with non-contiguous inputs with custom
        # attn_mask,
        # Reference: https://github.com/pytorch/pytorch/issues/112577.
        if query_states.device.type == "cuda" and attention_mask is not None:
            query_states = query_states.contiguous()
            key_states = key_states.contiguous()
            value_states = value_states.contiguous()

        # We dispatch to SDPA's Flash Attention or Efficient kernels via this `is_causal` if statement instead of an
        # inline conditional assignment
        # in SDPA to support both torch.compile's dynamic shapes and full graph options. An inline conditional prevents
        # dynamic shapes from compiling.
        # The q_len > 1 is necessary to match with AttentionMaskConverter.to_causal_4d that does not create a causal
        # mask in case q_len == 1.
        is_causal = True if causal_mask is None and q_len > 1 else False

        if q_len == 1:
            is_causal = False
            causal_mask = torch.ones(
                bsz,
                1,
                1,
                key_states.shape[2],
                device=hidden_states.device,
                dtype=hidden_states.dtype,
            ).contiguous()
            causal_mask = causal_mask.to(torch.bool)

        attn_output = torch.nn.functional.scaled_dot_product_attention(
            query_states,
            key_states,
            value_states,
            attn_mask=causal_mask,
            dropout_p=self.attention_dropout if self.training else 0.0,
            is_causal=is_causal,
        )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.view(bsz, q_len, self.hidden_size)

        attn_output = self.o_proj(attn_output)

        return attn_output, None, past_key_value


QWEN2_5_VL_ATTENTION_CLASSES = {
    "eager": Qwen25VLAttention,
    "flash_attention_2": Qwen25VLFlashAttention2,
    "sdpa": Qwen25VLSdpaAttention,
}


QWEN2_5_VL_INPUTS_DOCSTRING = r"""
    Args:
        input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
            Indices of input sequence tokens in the vocabulary. Padding will be ignored by default should you provide
            it.

            Indices can be obtained using [`AutoTokenizer`]. See [`PreTrainedTokenizer.encode`] and
            [`PreTrainedTokenizer.__call__`] for details.

            [What are input IDs?](../glossary#input-ids)
        attention_mask (`torch.Tensor` of shape `(batch_size, sequence_length)`, *optional*):
            Mask to avoid performing attention on padding token indices. Mask values selected in `[0, 1]`:

            - 1 for tokens that are **not masked**,
            - 0 for tokens that are **masked**.

            [What are attention masks?](../glossary#attention-mask)

            Indices can be obtained using [`AutoTokenizer`]. See [`PreTrainedTokenizer.encode`] and
            [`PreTrainedTokenizer.__call__`] for details.

            If `past_key_values` is used, optionally only the last `decoder_input_ids` have to be input (see
            `past_key_values`).

            If you want to change padding behavior, you should read [`modeling_opt._prepare_decoder_attention_mask`]
            and modify to your needs. See diagram 1 in [the paper](https://arxiv.org/abs/1910.13461) for more
            information on the default strategy.

            - 1 indicates the head is **not masked**,
            - 0 indicates the head is **masked**.
        position_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Indices of positions of each input sequence tokens in the position embeddings. Selected in the range `[0,
            config.n_positions - 1]`. [What are position IDs?](../glossary#position-ids)
        past_key_values (`tuple(tuple(torch.FloatTensor))`, *optional*, returned when `use_cache=True` is passed or when
        `config.use_cache=True`):
            Tuple of `tuple(torch.FloatTensor)` of length `config.n_layers`, with each tuple having 2 tensors of shape
            `(batch_size, num_heads, sequence_length, embed_size_per_head)`) and 2 additional tensors of shape
            `(batch_size, num_heads, encoder_sequence_length, embed_size_per_head)`.

            Contains pre-computed hidden-states (key and values in the self-attention blocks and in the cross-attention
            blocks) that can be used (see `past_key_values` input) to speed up sequential decoding.

            If `past_key_values` are used, the user can optionally input only the last `decoder_input_ids` (those that
            don't have their past key value states given to this model) of shape `(batch_size, 1)` instead of all
            `decoder_input_ids` of shape `(batch_size, sequence_length)`.
        inputs_embeds (`torch.FloatTensor` of shape `(batch_size, sequence_length, hidden_size)`, *optional*):
            Optionally, instead of passing `input_ids` you can choose to directly pass an embedded representation. This
            is useful if you want more control over how to convert `input_ids` indices into associated vectors than the
            model's internal embedding lookup matrix.
        use_cache (`bool`, *optional*):
            If set to `True`, `past_key_values` key value states are returned and can be used to speed up decoding (see
            `past_key_values`).
        output_attentions (`bool`, *optional*):
            Whether or not to return the attentions tensors of all attention layers. See `attentions` under returned
            tensors for more detail.
        output_hidden_states (`bool`, *optional*):
            Whether or not to return the hidden states of all layers. See `hidden_states` under returned tensors for
            more detail.
        return_dict (`bool`, *optional*):
            Whether or not to return a [`~utils.ModelOutput`] instead of a plain tuple.
        pixel_values (`torch.FloatTensor` of shape `(seq_length, num_channels * image_size * image_size)):
            The tensors corresponding to the input images. Pixel values can be obtained using
            [`AutoImageProcessor`]. See [`Qwen2_5_VLImageProcessor.__call__`] for details. [`Qwen2_5_VLProcessor`] uses
            [`Qwen2_5_VLImageProcessor`] for processing images.
        pixel_values_videos (`torch.FloatTensor` of shape `(seq_length, num_channels * temporal_size * image_size *
        image_size)):
            The tensors corresponding to the input videos. Pixel values can be obtained using
            [`AutoImageProcessor`]. See [`Qwen2_5_VLImageProcessor.__call__`] for details. [`Qwen2_5_VLProcessor`] uses
            [`Qwen2_5_VLImageProcessor`] for processing videos.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
            The rope index difference between sequence length and multimodal rope.
"""


__all__ = [
    "Qwen25VLPreTrainedModel",
]
